package org.apache.commons.lang3.math;

import java.io.*;
import java.lang.reflect.Array;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen0Test {

    @Test
    public void testCreateNumber_Null() {
        assertNull("Null input should return null", NumberUtils.createNumber(null));
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumber_Blank() {
        NumberUtils.createNumber("   ");
    }

    @Test
    public void testCreateNumber_HexInteger() {
        // Test hex prefixes and integer size logic
        assertEquals(Integer.valueOf(10), NumberUtils.createNumber("0x1234").getClass().equals(Integer.class) ? NumberUtils.createNumber("0x1234") : null);
        // Hex logic: hexDigits (4) <= 8 -> Integer
        assertTrue(NumberUtils.createNumber("0x1234") instanceof Integer);
        // Hex logic: hexDigits (9) > 8 -> Long
        assertTrue(NumberUtils.createNumber("0x123456789") instanceof Long);
        // Hex logic: hexDigits (17) > 16 -> BigInteger
        assertTrue(NumberUtils.createNumber("0x12345678901234567") instanceof BigInteger);

        // Test other prefixes
        assertTrue(NumberUtils.createNumber("0XABC") instanceof Integer);
        assertTrue(NumberUtils.createNumber("-0x12") instanceof Integer);
        assertTrue(NumberUtils.createNumber("-0X12") instanceof Integer);
        assertTrue(NumberUtils.createNumber("#abc") instanceof Integer);
        assertTrue(NumberUtils.createNumber("-#abc") instanceof Integer);
    }

    @Test
    public void testCreateNumber_IntegerLongBigInteger() {
        // No decimal, no exponent
        assertTrue(NumberUtils.createNumber("123") instanceof Integer);
        assertTrue(NumberUtils.createNumber("1234567890123") instanceof Long);
        assertTrue(NumberUtils.createNumber("12345678901234567890123") instanceof BigInteger);
    }

    @Test
    public void testCreateNumber_FloatDoubleBigDecimal() {
        // <= 7 decimals -> Float
        assertTrue(NumberUtils.createNumber("1.234567") instanceof Float);
        // 8-16 decimals -> Double
        assertTrue(NumberUtils.createNumber("1.23456789012345") instanceof Double);
        // > 16 decimals -> BigDecimal
        assertTrue(NumberUtils.createNumber("1.234567890123456789") instanceof BigDecimal);

        // Exponent logic
        assertTrue(NumberUtils.createNumber("1e2") instanceof Integer); // 1e2 is 100
        assertTrue(NumberUtils.createNumber("1.2e2") instanceof Float);
    }

    @Test
    public void testCreateNumber_Suffixes() {
        // Long suffix 'L'
        assertTrue(NumberUtils.createNumber("123L") instanceof Long);
        assertTrue(NumberUtils.createNumber("-123L") instanceof Long);
        assertTrue(NumberUtils.createNumber("12345678901234567890L") instanceof BigInteger);

        // Float suffix 'F'
        assertTrue(NumberUtils.createNumber("123.45F") instanceof Float);

        // Double suffix 'D'
        assertTrue(NumberUtils.createNumber("123.45D") instanceof Double);
        assertTrue(NumberUtils.createNumber("123.45d") instanceof Double);

        // Invalid suffix
        try {
            NumberUtils.createNumber("123X");
            fail("Should throw NumberFormatException for invalid suffix");
        } catch (NumberFormatException e) {}
    }

    @Test
    public void testCreateNumber_EdgeCases() {
        // Test allZeros logic for float/double precision check
        // If allZeros is true, it avoids returning float/double if it would lose precision
        // However, the code checks: if (!(f.isInfinite() || (f.floatValue() == 0.0F && !allZeros)))
        assertTrue(NumberUtils.createNumber("0.0000000000000000001") instanceof BigDecimal);

        // Test exponent bounds
        try {
            NumberUtils.createNumber("1.2e"); 
            // Depending on implementation of substring/indexOf, this might throw or behave
        } catch (Exception e) {}

        try {
            NumberUtils.createNumber("1.2e1.2"); // Invalid exponent
            fail();
        } catch (NumberFormatException e) {}
    }

    @Test
    public void testCreateNumber_NegativeHex() {
        // -0x12 is handled by pfxLen logic
        assertTrue(NumberUtils.createNumber("-0x12") instanceof Integer);
    }

    @Test
    public void testCreateNumber_Exponent_IOOBE_Prevention() {
        // Test the expPos < decPos check
        try {
            NumberUtils.createNumber("1e2.3");
            fail();
        } catch (NumberFormatException e) {}
    }

    @Test
    public void testCreateNumber_LargeFloatPrecision() {
        // A very large number that would be infinite in Float
        // Should fall through to Double or BigDecimal
        NumberUtils.createNumber("1e40F"); 
        NumberUtils.createNumber("1e40D");
    }

    @Test
    public void testCreateNumber_DecimalOnly() {
        assertTrue(NumberUtils.createNumber("123.") instanceof Float);
    }
}
